llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Isradipine, a lipophilic dihydropyridine, had a mean systemic availability of 16.5% in healthy volunteers after oral administration, providing direct threshold-relevant evidence of F below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Nifedipine, a small dihydropyridine, has oral bioavailability of about 45% in humans, which is above the 20% threshold and would support high if transferred.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "A larger pyrazolopyrimidinone analogue showed 34% oral bioavailability in healthy volunteers, above the threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Nabumetone's active metabolite had 38% absolute bioavailability in healthy subjects, above the threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Elagolix is reported to have good oral bioavailability in humans, above the threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a large, highly lipophilic polyprenyl benzoquinone (CoQ10) with no ionizable groups and very poor aqueous solubility, which strongly limits oral absorption. The only threshold-relevant low-F evidence (isradipine, F~16-19%) supports low, while the high-F records come from smaller, more soluble drug-like molecules whose absorption and first-pass characteristics are not transferable to this extreme lipophilic quinone.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No structurally close analogue with measured F; retrieved evidence is from small heterocyclic drugs with different rate-limiting steps (first-pass metabolism vs dissolution/lymphatic absorption)."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

